import { type Command, Mount } from "@effect/ui";
import { Effect, Queue, Schema, Stream } from "effect";

/**
 * A Schema of upstream's own type `T` that accepts any value. Element properties and mount args are typed by
 * upstream's declarations and checked by the library itself, so the facade restates no type and validates nothing.
 */
export const typed = <T>(): Schema.declare<T> => Schema.declare((_: unknown): _ is T => true);

/** The `detail` of a DOM event as upstream declares it in `GlobalEventHandlersEventMap`, else `unknown`. */
export type DetailOf<K extends string> = K extends keyof GlobalEventHandlersEventMap
	? GlobalEventHandlersEventMap[K] extends CustomEvent<infer D>
		? D
		: unknown
	: unknown;

/**
 * A mount reporting a form control's state each time it fires `input` or `change`: the properties `keys` of the
 * element itself, typed by upstream (`HTMLElementTagNameMap[tag]`). Effect UI's own payload for these events reads
 * only `value`, and a form-associated custom element's state (a switch's `checked`) is on its properties.
 */
export const changesMount = <E extends object, const K extends keyof E & string>(name: string, keys: ReadonlyArray<K>) =>
	Mount.makeStream(name, { args: {} }, (node: HTMLElement) =>
		Stream.callback<{ readonly event: "input" | "change" } & Pick<E, K>>((queue) =>
			Effect.acquireRelease(
				Effect.sync(() => {
					// The binding mounts it only on its own element: `node` is an `E` (whose mixin types may not say HTMLElement).
					const element = node as unknown as E;
					const listener = (event: Event) => {
						const state = Object.fromEntries(keys.map((key) => [key, element[key]])) as Pick<E, K>;
						Queue.offerUnsafe(queue, { event: event.type === "input" ? "input" : "change", ...state });
					};
					node.addEventListener("input", listener);
					node.addEventListener("change", listener);
					return listener;
				}),
				(listener) =>
					Effect.sync(() => {
						node.removeEventListener("input", listener);
						node.removeEventListener("change", listener);
					}),
			),
		),
	);

/** How an upstream instance lives on an element. */
export interface InstanceSpec<Node, Args, Instance, Message> {
	/** Creates the instance on the element, from the first args. */
	readonly create: (node: Node, args: Args) => Instance;
	/** Releases it: called when the element goes, and before a recreation. */
	readonly release: (instance: Instance) => void;
	/**
	 * Applies new args to the live instance. Without it, the instance is released and created again, which is always
	 * correct and costs a full re-render of the library's view.
	 */
	readonly update?: ((instance: Instance, next: Args, previous: Args) => void) | undefined;
	/** Subscribes to the instance's events, sending each as a message with `emit`; returns how to unsubscribe. */
	readonly events?: ((instance: Instance, emit: (message: Message) => void) => () => void) | undefined;
}

/**
 * A mount that keeps one upstream instance on its element: created when the element is committed, updated (or
 * created again) when the view's args change, its events sent as messages, and released when the element goes.
 */
export const instanceMount = <const Name extends string, const In extends Command.ArgsInput, Node, Instance, Message>(
	name: Name,
	options: { readonly args: In },
	spec: InstanceSpec<Node, Command.ArgsOf<In>, Instance, Message>,
) =>
	Mount.makeStream(name, options, (node: Node, initial, changes) =>
		Stream.callback<Message>((queue) =>
			Effect.gen(function* () {
				const emit = (message: Message) => {
					Queue.offerUnsafe(queue, message);
				};
				const start = (args: Command.ArgsOf<In>) => {
					const instance = spec.create(node, args);
					return { instance, unsubscribe: spec.events?.(instance, emit) ?? (() => {}) };
				};
				const stop = (live: { readonly instance: Instance; readonly unsubscribe: () => void }) => {
					live.unsubscribe();
					spec.release(live.instance);
				};
				let live = start(initial);
				let current = initial;
				yield* Effect.addFinalizer(() => Effect.sync(() => stop(live)));
				yield* changes.pipe(
					Stream.runForEach((next) =>
						Effect.sync(() => {
							// Effect UI's `changes` begins with the args the instance was created from: not a change.
							if (next === current) return;
							if (spec.update === undefined) {
								stop(live);
								live = start(next);
							} else {
								spec.update(live.instance, next, current);
							}
							current = next;
						}),
					),
					Effect.forkScoped,
				);
			}),
		),
	);
